204	    #[track_caller]
205	    pub fn edit(&mut self, replace: Range<usize>, with: &str) {
206	        let start_byte = replace.start;
207	        let start_utf16 = self.byte_to_utf16(start_byte).unwrap();
208	        let line = self.byte_to_line(start_byte).unwrap();
